import React, { ReactNode, useState } from 'react'
import { themes } from '../../Models/Theme';
import { useOutletContext } from 'react-router';
import TitlebarCustom from '../../Components/Titlebar/TitlebarCustom';
import { CameraIcon, GearIcon, LockIcon, NotifIcon, PaletteIcon, SignoutIcon, UserIcon } from '../../Models/Icon';
import MenuItemList from '../../Components/MenuItem/MenuItemList';

interface ThemeContextType {
  theme: string;
  updateTheme: (color: string) => void;
}

const AccountPage = () => {
  const { theme, updateTheme } = useOutletContext<ThemeContextType>();
  const [isThemeOpen, setThemeOpen] = useState(false);

  return (
    <div className='flex flex-col'>
        <TitlebarCustom
          rightIcon={<></>}
          content='Account'
          rightAction={() => {}}
        />

        <div className="page-content">
          
          {/* Profile Card */}
          <div className="section flex flex-col items-center text-center !bg-theme-0">
            <div className="relative">
              <img 
                src="https://i.pravatar.cc/150?u=a042581f4e29026704d" 
                className="avatar w-24 h-24"
              />
              <button className="absolute bottom-0 right-0 bg-theme-600 text-theme-0 p-2 rounded-full shadow-md border-2 border-theme-0">
                {/* for update photo */}
                <CameraIcon className="text-xs" />
              </button>
            </div>
            <h3 className="title-text mt-4">Alexander Pierce</h3>
            <p className="desc-text">Senior Staff Manager</p>
          </div>

          {/* Settings Menu Groups */}
          <div className="section !p-0 overflow-hidden">
             <MenuItemList isOpen={false} iconItem={<UserIcon />} label="Personal Information" onClick={() => {}} />
             <MenuItemList isOpen={false} iconItem={<LockIcon />} label="Security & Password" onClick={() => {}} />
             <MenuItemList isOpen={false} iconItem={<NotifIcon />} label="Notifications" onClick={() => {}} />
             <MenuItemList isOpen={isThemeOpen} iconItem={<PaletteIcon />} label="Theme" onClick={() => {setThemeOpen(!isThemeOpen)}} />

             <div className={`overflow-hidden animate bg-theme-50 ${isThemeOpen ? 'h-auto opacity-100 p-4' : 'h-0 opacity-0'}`}>
               <div className="flex flex-wrap gap-4 justify-center">
                {themes.map((t) => (
                  <button
                    key={t.value}
                    onClick={() => updateTheme(t.value)}
                    className={`w-5 h-10 rounded-xl ${t.class} animate active:scale-90 shadow-sm flex items-center justify-center
                      ${theme === t.value ? 'ring-2 ring-offset-2 ring-theme-600 scale-110' : 'opacity-80'}`}
                  >
                    {theme === t.value && <div className="w-2 h-2 bg-white rounded-full shadow-sm" />}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="section !p-0 overflow-hidden">
             <MenuItemList 
                isOpen={false}
                iconItem={<SignoutIcon />} 
                label="Logout" 
                onClick={() => console.log("Logout")} 
             />
          </div>

          {/* Version Info (Footer) */}
          <div className="text-center pb-10">
            <p className="desc-text !text-[10px] uppercase tracking-widest opacity-50">
              Version 1.0.2 (2026)
            </p>
          </div>

        </div>
    </div>
  )
}

export default AccountPage