import React from 'react'
import { Announcement } from '../../Models/Announcement';
import { formatColor } from '../../Helpers/formatColor';
import { ChevronRIcon } from '../../Models/Icon';

interface Props {
    item: Announcement;
}

const AnnouncementItem = ({item}: Props) => {
  return (
    <div className="flex-shrink-0 w-[85%] bg-theme-0 p-4 rounded-3xl border border-theme-100 shadow-sm relative overflow-hidden">
        <div className={`absolute top-0 right-0 w-24 h-24 bg-${item.color}-700 opacity-50 -mr-8 -mt-10 rounded-full`}></div>
 
        <div className="relative flex flex-col gap-2">
            <div>
                <span className={`category-box-subtext ${formatColor(item.color)}`}>
                    {item.category}
                </span>
            </div>
            <h4 className="text-sm font-bold text-theme-900 leading-snug">
                {item.title}
            </h4>

            <div className="flex justify-between items-center">
                <span className="text-[11px] text-theme-400 font-medium">{item.date}</span>
                <button className="flex items-center gap-2 expand-subtext">
                    Read More <ChevronRIcon />
                </button>
            </div>
        </div>
    </div>
  )
}

export default AnnouncementItem