import React from 'react'
import { formatColor } from '../../Helpers/formatColor'
import { Task } from '../../Models/Task'
import { ChevronRIcon } from '../../Models/Icon';

interface Props {
    task: Task;
}

const TaskItem = ({task}: Props) => {
  return (
    <div className="menu-item w-full flex flex-col gap-2">
        <div className="flex justify-between">
            <span className={`category-box-subtext ${formatColor('theme')}`}>{task.category}</span>

            <span className={`text-[10px] px-2 py-0.5 rounded-full font-medium ${formatColor(task.statusColor)}`}>
                {task.status}
            </span>
        </div>
 
        <div className="flex gap-2">
            <p className="flex-1 title-subtext">{task.task}</p>
            <ChevronRIcon className='text-theme-300' />
        </div>
 
    </div>
  )
}

export default TaskItem