import { dateFnsLocalizer, Navigate, View } from 'react-big-calendar'
import { format, parse, startOfWeek, getDay } from 'date-fns'
import { enUS, enGB } from 'date-fns/locale'
import { ChevronLIcon, ChevronRIcon } from '../Models/Icon'

// This is the "Localizer"
const locales = {
  'en-US': enUS,
}

export const calendarLocalizer = dateFnsLocalizer({
  format,        // How to display: "Jan 14"
  parse,         // How to read: "2026-01-14"
  startOfWeek,   // Should the week start on Sunday or Monday?
  getDay,        // What day of the week is it? (0-6)
  locales,       // Language support
})

export const getCalendarFormats = (is24Hour: boolean) => ({
  // for week and day time
  timeGutterFormat: (date: Date, culture: any, localizer: any) =>
    localizer.format(date, is24Hour ? 'HH:mm' : 'h:mm a', culture),
 
  // for event time
  eventTimeRangeFormat: ({ start, end }: any, culture: any, localizer: any) =>
    localizer.format(start, is24Hour ? 'HH:mm' : 'h:mm a', culture) +
    ' — ' +
    localizer.format(end, is24Hour ? 'HH:mm' : 'h:mm a', culture),

  // agenda title
  agendaHeaderFormat: ({ start, end }: { start: Date; end: Date }, culture: any, localizer: any) => {
    const s = localizer.format(start, 'dd MMM yyyy', culture);
    const e = localizer.format(end, 'dd MMM yyyy', culture);
    return `${s} — ${e}`;
  },

  // agenda list
  agendaDateFormat: (date: Date, culture: any, localizer: any) =>
    localizer.format(date, 'dd MMM', culture),

  // week title
  dayRangeHeaderFormat: (date: any, culture: any, localizer: any) => {
    // In week view, 'date' is an object { start: Date, end: Date }
    if (date.start && date.end) {
      const { start, end } = date;
      const monthName = localizer.format(start, 'MMM', culture);
      const startDay = localizer.format(start, 'd', culture);
      const endDay = localizer.format(end, 'd', culture);
 
      // If the week is within the same month
      if (start.getMonth() === end.getMonth()) {
        return `${startDay} – ${endDay} ${monthName}`;
      }
 
      // If the week spans two months (e.g., "29 Jan – 04 Feb")
      const endMonthName = localizer.format(end, 'MMM', culture);
      return `${startDay} ${monthName} – ${endDay} ${endMonthName}`;
    }
    return localizer.format(date, 'MMMM yyyy', culture);
  },

  // day title
  dayHeaderFormat: (date: Date, culture: any, localizer: any) =>
    localizer.format(date, 'EEE dd MMM', culture),
 
  // month header
  weekdayFormat: (date: Date, culture: any, localizer: any) =>
    localizer.format(date, 'EEE', culture),

  // week header
  dayFormat: (date: Date, culture: any, localizer: any) =>
    localizer.format(date, 'EEE dd', culture),
 
  // day cell
  dateFormat: (date: Date, culture: any, localizer: any) =>
    localizer.format(date, 'dd', culture),
});

export const getCalenderToolbar = (toolbar: any) => {
  const { label, date, onNavigate, onView, view, views } = toolbar;

  const goToBack = () => onNavigate(Navigate.PREVIOUS);
  const goToNext = () => onNavigate(Navigate.NEXT);
  const goToCurrent = () => onNavigate(Navigate.TODAY);

  return (
    <div className="flex flex-col md:flex-row items-center justify-between gap-4 p-2">
      <div className="flex flex-col md:flex-row items-center gap-4">
        {/* View Switcher */}
        <div className="flex bg-theme-100 p-1 rounded-xl">
          {(views as View[]).map((name) => (
            <button
              key={name}
              onClick={() => onView(name)}
              className={`px-4 py-1 title-subtext rounded-lg animate ${
                view === name 
                ? 'bg-theme-0 !text-theme-900 shadow-sm' 
                : '!text-theme-700'
              }`}
            >
              {name.charAt(0).toUpperCase() + name.slice(1)}
            </button>
          ))}
        </div>

        {/* Navigation Buttons */}
        <div className="flex bg-theme-100 p-1 rounded-xl">
          <button onClick={goToBack} className="title-subtext p-2 rounded-lg">
            <ChevronLIcon />
          </button>
          <button onClick={goToCurrent} className="title-subtext px-4 py-1 rounded-lg">
            Today
          </button>
          <button onClick={goToNext} className="title-subtext p-2 rounded-lg">
            <ChevronRIcon />
          </button>
        </div>

      </div>

      {/* Title */}
      <h2 className="title-text">
        {label}
      </h2>
    </div>
  );
};