import React from 'react'

interface Props {
  isOpen: boolean;
  title: string;
  message: string;
  onClose: () => void;
  onConfirm: () => void;
}

const Modal = ({isOpen, title, message, onClose, onConfirm}: Props) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
      <div className="bg-theme-50 rounded-2xl shadow-xl max-w-sm w-full overflow-hidden border border-theme-200">
        <div className="p-4">
          <h3 className="title-text">
            {title}
          </h3>
          <p className="desc-text">
            {message}
          </p>
        </div>

        {/* Action Buttons */}
        <div className="flex gap-3 p-4">
          <button
            onClick={onClose}
            className="flex-1 btn-text-center blank"
          >
            Cancel
          </button>
          <button
            onClick={onConfirm}
            className="flex-1 btn-text-center full"
          >
            Confirm
          </button>
        </div>
      </div>
    </div>
  )
}

export default Modal