import React from 'react'
import { ClockIcon } from '../../Models/Icon'
import { formatColor } from '../../Helpers/formatColor'

interface Props {}

const SectionSchedule = (props: Props) => {
  return (
    <div className="section">
        <div className="flex justify-between items-center mb-4">
            <h4 className="title-text flex items-center gap-2"><ClockIcon /> Today's Schedule</h4>
        </div>
 
        <div className="space-y-3">
        <div className="flex justify-between items-center desc-text">
            <span>Shift Start</span>
            <span className="font-semibold text-theme-900">09:00</span>
        </div>
        <div className="flex justify-between items-center desc-text">
            <span>Break Time</span>
            <span className="font-semibold text-theme-900">12:00 - 13:00</span>
        </div>
        <div className="flex justify-between items-center desc-text border-t border-theme-600 pt-3">
            <span>Status</span>
            <span className={`category-box-text ${formatColor('amber')}`}>
                Not Clocked In
            </span>
        </div>
        </div>
    </div>
  )
}

export default SectionSchedule