import React, { ReactNode } from 'react'
import { ChevronRIcon } from '../../Models/Icon';

interface Props {
    isOpen: boolean;
    iconItem: ReactNode;
    label: string;
    onClick: () => void;
}

const MenuItemList = ({isOpen, iconItem, label, onClick}: Props) => {
  return (
        <button onClick={onClick}
            className="menu-item w-full flex items-center gap-4"
        >
            <div className={`category-box-text bg-theme-100 text-theme-700`}>
                {iconItem}
            </div>
            <span className="flex-1 title-subtext text-left capitalize">{label}</span>        
            <ChevronRIcon className={`text-theme-300 text-sm animate ${isOpen ? 'rotate-90' : 'rotate-0'}`} />
        </button>
  )
}

export default MenuItemList