import React, { useEffect, useState } from 'react'
import { CalenderIcon, SigninIcon } from '../../Models/Icon'
import { formatDate, formatTime } from '../../Helpers/formatDate'

interface Props {}

const SectionAttendance = (props: Props) => {
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 1000);

    return () => clearInterval(timer);
  }, []);

  return (
    <div className="section-dark flex flex-col justify-between">
        <div>
            <div className="flex items-center gap-2 text-theme-0 mb-1">
                <CalenderIcon className="text-sm" />
                <span className="text-sm font-medium">{formatDate(currentTime)}</span>
            </div>
            <h3 className="text-3xl text-theme-0 font-bold mb-4 tracking-widest">{formatTime(currentTime)}</h3>
        </div>

        <button className="btn-text-center blank"><SigninIcon /> Check In</button>
    </div>
  )
}

export default SectionAttendance