import React from 'react'
import { NotifIcon } from '../../Models/Icon'
import { useNavigate } from 'react-router'

interface Props {}

const Titlebar = (props: Props) => {
  const navigate = useNavigate();
  return (
    <div className="bg-theme-50 flex items-center justify-between p-6 rounded-b-xl">
        <div onClick={() => {navigate('account')}}
            className="relative cursor-pointer p-2 rounded-full">
            <img
                src="https://i.pravatar.cc/150?u=a042581f4e29026704d" // Example avatar
                alt="Profile"
                className="avatar w-12 h-12"
            />
        </div>
        <div className="text-center flex-1">
            <p className="desc-text">Good Morning,</p>
            <h4 className="title-text">Alexander Pierce</h4>
        </div>
        <div className="icon-titlebar">
            <NotifIcon />
            <span className="absolute top-2 right-2.5 w-2.5 h-2.5 bg-red-500 border-2 border-theme-0 rounded-full"></span>
        </div>
    </div>
  )
}

export default Titlebar