import React, { ReactNode } from 'react'
import { ChevronLIcon, NotifIcon } from '../../Models/Icon'
import { useNavigate } from 'react-router';

interface Props {
    content: string;
    rightIcon: ReactNode;
    rightAction: () => void;
}

const TitlebarCustom = ({content, rightIcon, rightAction}: Props) => {
  const navigate = useNavigate();

  const handleBack = () => {
    navigate(-1);
  };

  return (
    <div className="bg-theme-50 flex items-center justify-between p-6 rounded-b-xl">
        <div className="icon-titlebar" onClick={handleBack}>
            <ChevronLIcon />
        </div>
        <div className="text-center flex-1">
            <p className="title-text">{content}</p>
        </div>
        <div className="icon-titlebar" onClick={rightAction}>
            {rightIcon}
        </div>
    </div>
  )
}

export default TitlebarCustom