import React, { useState } from 'react'
import { Link } from 'react-router'
import { CalenderIcon, CalenderPlusIcon, FileSignIcon, HomeIcon, InboxIcon, LayerIcon, PlusIcon, UserIcon } from '../../Models/Icon'
import MenuItem from '../MenuItem/MenuItem';

interface Props {}

const Navbar = (props: Props) => {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <>
      {/* the hidden menu */}
      <div className={`fixed inset-x-0 bottom-20 mx-auto w-[90%] max-w-sm z-50 
        animate ${isOpen ? "scale-100 opacity-100 translate-y-0" : "scale-90 opacity-0 translate-y-10 pointer-events-none"
      }`}>
        <div className="section !bg-theme-100">
          <div className="grid grid-cols-3 gap-4">
            <MenuItem icon={<LayerIcon />} label="Add Task" />
            <MenuItem icon={<CalenderPlusIcon />} label="Add Agenda" />
            <MenuItem icon={<FileSignIcon />} label="Request" />
          </div>
        </div>
      </div>

      {/* black background */}
      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/30 backdrop-blur-[2px] z-40 transition-opacity" 
          onClick={() => setIsOpen(false)} 
        />
      )}

    <nav className='flex justify-between p-2 bg-theme-200 rounded-t-xl'>
        <Link to="/" className="navbar-item">
            <HomeIcon />
            {/* <span>Home</span> */}
        </Link>
        <Link to="calendar" className="navbar-item">
            <CalenderIcon />
            {/* <span>Calender</span> */}
        </Link>
        <div className='navbar-item pointer-events-none' onClick={(e) => e.stopPropagation()}></div>
        <div className="relative">
            <button onClick={() => setIsOpen(!isOpen)}
              className={`absolute left-1/2 -translate-x-1/2
                w-16 h-16 bg-theme-600 rounded-full 
                navbar-item !text-theme-0 
                border-[6px] border-theme-gray shadow-xl
                animate
                ${isOpen ? "-top-2 rotate-45" : " -top-10 rotate-0"}`}>
              <PlusIcon />
            </button>
        </div>
        <div className='navbar-item pointer-events-none' onClick={(e) => e.stopPropagation()}></div>
        <Link to="/" className="navbar-item">
            <InboxIcon />
            {/* <span>Inbox</span> */}
        </Link>
        <Link to="account" className="navbar-item">
            <UserIcon />
            {/* <span>Account</span> */}
        </Link>
    </nav>
    </>
  )
}

export default Navbar