import React from 'react'
import { v4 as uuid } from "uuid";
import { BullHornIcon } from '../../Models/Icon'
import { announcements } from '../../Models/Announcement'
import AnnouncementItem from './AnnouncementItem'

interface Props {}

const SectionAnnouncement = (props: Props) => {
  return (
    <>
        <div className="flex justify-between items-center px-2">
            <div className="flex items-center gap-2">
                <div className="p-2 bg-amber-100 rounded-lg text-amber-700">
                    <BullHornIcon className="text-sm" />
                </div>
                <h4 className="title-text">What's New</h4>
            </div>
            <button className="expand-text">View All</button>
        </div>
        <div className="flex overflow-x-auto gap-2 px-4 -mx-4">
            {announcements.map((item) => (
                <AnnouncementItem key={uuid()} item={item} />
            ))}
        </div>
    </>
  )
}

export default SectionAnnouncement