import React, { useState } from 'react'
import Modal from '../../Components/Modals/Modal';
import Titlebar from '../../Components/Titlebar/Titlebar';
import SectionAnnouncement from '../../Components/SectionAnnouncement/SectionAnnouncement';
import SectionAttendance from '../../Components/SectionAttendance/SectionAttendance';
import SectionSchedule from '../../Components/SectionSchedule/SectionSchedule';
import SectionTeam from '../../Components/SectionTeam/SectionTeam';
import SectionTask from '../../Components/SectionTask/SectionTask';

interface Props {}

const HomePage = (props: Props) => {
  const [isModalOpen, setIsModalOpen] = useState(false);

  const handleCloseModal = () => {
    setIsModalOpen(false);
  };

  return (
    <div className='flex flex-col'>
        <Titlebar />

        <div className='page-content'>
            <SectionAnnouncement />
            <SectionAttendance />
            <SectionSchedule />
            <SectionTeam />
            <SectionTask />
        </div>

        <Modal 
            isOpen={isModalOpen}
            onClose={() => setIsModalOpen(false)}
            onConfirm={handleCloseModal}
            title="Are you sure?"
            message="This action cannot be undone. This will permanently delete your data from our servers."
        />
    </div>
  )
}

export default HomePage