import React from 'react'
import { Staff } from '../../Models/Staff'

interface Props {
    member: Staff;
}

const AvatarMember = ({member}: Props) => {
  return (
    <div className="relative flex-shrink-0">
        <img 
            src={member.avatar} 
            alt={member.name} 
            className="w-10 h-10 rounded-full object-cover" 
        />
        <span className={`absolute bottom-0 right-0 w-3 h-3 rounded-full border-2 border-theme-0 ${member.status === 'Working' ? 'bg-green-500' : 'bg-gray-300'}`}></span>
    </div>
  )
}

export default AvatarMember