import React, { useCallback, useMemo, useState } from 'react'
import 'react-big-calendar/lib/css/react-big-calendar.css';
import './CalendarPage.css';
import { Calendar, View, Views } from 'react-big-calendar';
import { calendarLocalizer, getCalendarFormats, getCalenderToolbar } from '../../Helpers/calendarHelper';
import { isSameDay } from 'date-fns';
import TitlebarCustom from '../../Components/Titlebar/TitlebarCustom';
import { PlusIcon } from '../../Models/Icon';
import { events } from '../../Models/Event';

interface Props {}

const CalendarPage = (props: Props) => {
  const [date, setDate] = useState(new Date());
  const [view, setView] = useState<View>(Views.DAY);
  const [is24Hour, setIs24Hour] = useState(false);

  const formats = useMemo(() => getCalendarFormats(is24Hour), [is24Hour]);

  const onNavigate = useCallback((newDate: Date) => {
    setDate(newDate);
  }, []);

  const onView = useCallback((newView: View) => {
    setView(newView);
  }, []);

  return (
    <div className="flex flex-col h-screen">
        <div className="flex justify-end hidden">
            <button 
                onClick={() => setIs24Hour(!is24Hour)}
                className="bg-blue-600 text-theme-0 px-4 py-2 rounded shadow-md hover:bg-blue-700 transition"
            >
                Switch to {is24Hour ? '12h' : '24h'} Format
            </button>
        </div>

        <TitlebarCustom
          content='Calendar'
          rightIcon={<PlusIcon />}
          rightAction={() => {console.log("asd")}}
        />

        <div className="flex-1 bg-theme-50">
            <Calendar
                localizer={calendarLocalizer}
                formats={formats}
                events={events} // Add your tasks here
 
                // Controlled props
                date={date}
                view={view}
 
                // Memoized handlers
                onNavigate={onNavigate}
                onView={onView}
                getNow={() => new Date()}
                scrollToTime={new Date()}
                showAllEvents={true}
                //popup={true}
 
                // STYLE THE BARS
                eventPropGetter={(event) => {
                  // Check if the current view is Agenda
                  const isAgenda = view === 'agenda';

                  // Check if start and end are on the same day
                  const isPersistent = !isSameDay(event.start, event.end) || event.allDay;

                  // Define base classes
                  const agendaClass = `!border-l-4 !border-t-0 ${isPersistent ? '!border-theme-900' : '!border-theme-500'}`;
 
                  // Define classes for timed vs multi-day events
                  const monthWeekClass = isPersistent
                    ? "!bg-theme-900 !rounded-md !border-none !text-theme-0 !font-bold" // Distinct style for multi-day
                    : "!bg-theme-500 !rounded-lg !border-2 !border-theme-100 !text-theme-0 !shadow-sm"; // Single day style

                  return {
                    className: isAgenda ? agendaClass : `${monthWeekClass} !p-2`,
                  };
                }}

                // CUSTOM COMPONENTS
                components={{
                  event: ({ event }) => { 
                    const isAgenda = view === 'agenda';
                    if (isAgenda) {
                      return (
                        <div className="flex items-center"> 
                          <div className="flex flex-col">
                            <span>
                              {event.title}
                            </span>
                          </div>
                        </div>
                      );
                    }
 
                    return (
                      <div className="flex flex-col px-1">
                        <span className="event-calender-text">
                          {event.title}
                        </span>
                      </div>
                    )
                  },
                  toolbar: getCalenderToolbar,
 
                }}
 
                // Standard props
                startAccessor="start"
                endAccessor="end"
 
                style={{ height: 'auto', minHeight: '100%' }}
            />
        </div>
    </div>
  )
}

export default CalendarPage