import React from 'react'
import { v4 as uuid } from "uuid";
import { TasksIcon } from '../../Models/Icon';
import { tasks } from '../../Models/Task';
import TaskItem from './TaskItem';

interface Props {}

const SectionTask = (props: Props) => {
  return (
    <div className='section !p-0'>
        <div className="flex justify-between items-center p-4">
            <h4 className="title-text flex items-center gap-2"><TasksIcon /> Today's Tasks</h4>
            <button className="expand-text">See All</button>
        </div>

        <div className="w-full overflow-hidden rounded-2xl">
            {tasks.map((task) => (
                <TaskItem key={uuid()} task={task} />
            ))}
        </div>
    </div>
  )
}

export default SectionTask