import React, { useEffect, useState } from 'react';
import './App.css';
import { Outlet } from 'react-router';
import { Toaster } from 'sonner';
import { CheckIcon, WarningIcon } from './Models/Icon';
import Navbar from './Components/Navbar/Navbar';

function App() {
  const [isLandscape, setIsLandscape] = useState(false);

  const [theme, setTheme] = useState('blue');

  const updateTheme = (newTheme: string) => {
    setTheme(newTheme);
    //localStorage.setItem('app-theme', newTheme);
  };

  const checkOrientation = () => {
    setIsLandscape(window.innerWidth > window.innerHeight);
  };

  useEffect(() => {
    checkOrientation();
    window.addEventListener('resize', checkOrientation);
    return () => window.removeEventListener('resize', checkOrientation);
  }, []);

  return (
    <div data-theme={theme} className="App h-screen w-screen flex flex-col bg-theme-gray">
      <main className='flex-1 flex flex-col overflow-y-scroll'>
        <Outlet context={{ theme, updateTheme }} />
      </main>
 
      <Navbar />

      <Toaster 
        position={isLandscape ? "top-right" : "bottom-center"}
        visibleToasts={1} 
        richColors={false} // Turning this false allows custom styling
        icons={{
          success: <CheckIcon className="text-accept w-5 h-5" />,
          warning: <WarningIcon className="text-warning w-5 h-5" />,
        }}
        toastOptions={{
          style: { 
            background: 'white', 
            color: '#1f2937' 
          },
          className: 'border border-gray-100 shadow-lg'
        }}
      />
    </div>
  );
}

export default App;
